"""Build an isolated controller-enabled recorder from the audited E1 recorder."""
from pathlib import Path
root=Path(__file__).resolve().parent
s=(root/'contact_pilot.py').read_text(encoding='utf-8')
s=s.replace('parser=argparse.ArgumentParser()',"parser=argparse.ArgumentParser()\nparser.add_argument('--controller',choices=['nominal','high','oracle','mcf','scalar'],default='nominal')\nparser.add_argument('--checkpoint',type=Path)")
s=s.replace("from mcf import ContactFeatureStream","from mcf import ContactFeatureStream\n    from reflex_policy import Controller")
s=s.replace("initial_pose=(obj.data.root_link_pose_w[0].cpu().numpy().copy())", "initial_pose=(obj.data.root_link_pose_w[0].cpu().numpy().copy())\n        input_mcf=stream.update(initial_obs['tactile'])[1]\n        controller=Controller(args.controller,cfg.physics_dt,args.checkpoint)\n        nominal_action=action.copy()\n        previous_control_pose=initial_pose.copy()")
s=s.replace("'host_time_before_ns','host_time_after_ns','displacement_world_m','orientation_change_rad')", "'host_time_before_ns','host_time_after_ns','displacement_world_m','orientation_change_rad',\n              'input_mcf_before','expert_delta_rad','controller_delta_rad','controller_inference_ns','expert_linear_speed_m_s','expert_angular_speed_rad_s')")
s=s.replace("t=i*cfg.physics_dt\n            f,m,p=tr.wrench", "t=i*cfg.physics_dt\n            control_begin=time.perf_counter_ns()\n            previous_angle=2*np.arccos(np.clip(abs(np.dot(pose[3:7],initial_pose[3:7])),0,1))\n            # Differentiate realized link poses; solver velocities contain\n            # persistent contact stabilization terms even at stationary poses.\n            tangent_velocity=reference.T@(pose[:3]-previous_control_pose[:3])/cfg.physics_dt\n            tangent_velocity[2]=0.\n            qa=pose[3:7].astype(float); qa/=np.linalg.norm(qa)\n            qb=previous_control_pose[3:7].astype(float); qb/=np.linalg.norm(qb)\n            angular_rate=2*np.arccos(np.clip(abs(qa@qb),0,1))/cfg.physics_dt\n            realized_velocity=np.r_[tangent_velocity,angular_rate,0.,0.]\n            delta,teacher,speed,angular_speed=controller.step(input_mcf,realized_velocity,previous_angle)\n            previous_control_pose=pose.copy()\n            control_ns=time.perf_counter_ns()-control_begin\n            action=nominal_action.copy()\n            action[finger_ids]+=np.array([-1,1])*delta\n            if np.any(action<limits[:,0]) or np.any(action>limits[:,1]): raise ValueError('Reflex joint limits')\n            previous_input=input_mcf.copy()\n            f,m,p=tr.wrench")
s=s.replace("scalar,mcf=stream.update(obs['tactile'])", "scalar,mcf=stream.update(obs['tactile'])\n            input_mcf=mcf.copy()")
s=s.replace("values=dict(obs,scalar=scalar", "values=dict(obs,input_mcf_before=previous_input,expert_delta_rad=teacher,controller_delta_rad=delta,controller_inference_ns=control_ns,expert_linear_speed_m_s=speed,expert_angular_speed_rad_s=angular_speed,scalar=scalar")
s=s.replace("summary={'trial':tr.metadata()", "summary={'controller':args.controller,'trial':tr.metadata()")
s=s.replace("initial_close_rad=args.initial_close_rad,initial_target_offset_z_m", "controller=args.controller,checkpoint=str(args.checkpoint) if args.checkpoint else None,checkpoint_sha256=hashlib.sha256(args.checkpoint.read_bytes()).hexdigest() if args.checkpoint else None,\n        initial_close_rad=args.initial_close_rad,initial_target_offset_z_m")
s=s.replace("'sensor_slots':[", "'robot_body_names':list(env._robot.body_names),'sensor_slots':[")
s=s.replace("Path(__file__).with_name('disturbance.py'),", "Path(__file__).with_name('disturbance.py'),Path(__file__).with_name('reflex_policy.py'),Path(__file__).with_name('bounded_scaler.py'),")
(root/'reflex_sim.py').write_text(s,encoding='utf-8')
print('Built isolated reflex_sim.py')
